// Iterating with Foreach
string[] cars = {"Volvo", "BMW", "Ford"};
foreach (string i in cars) {
  Console.WriteLine(i);
}

// While Loop with Break
int i = 0;
while (i < 10) {
  Console.WriteLine(i);
  i++;
  if (i == 4) break; // Terminate early
}

